CREATE TABLE dbo.free_sql_exercises
(
    ExerciseID   INT IDENTITY(1,1) PRIMARY KEY,
    Software     NVARCHAR(50)  NOT NULL,
    Topic        NVARCHAR(100) NOT NULL,
    Level        NVARCHAR(50)  NOT NULL,
    Exercise     NVARCHAR(MAX) NOT NULL,
    Number       INT           NOT NULL
);
